import { existsSync } from 'node:fs'
import { mkdir } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import { migrate } from 'drizzle-orm/libsql/migrator'
import { defineNitroPlugin } from 'nitropack/runtime'
import { useRuntimeConfig } from 'nuxt/server'

/** Applies pending migrations from server/database/migrations when the server starts. A project without entities has none yet. */
export default defineNitroPlugin(async () => {
  const { db } = useRuntimeConfig()
  const migrationsFolder = resolve(process.cwd(), db.migrationsDir)
  if (!existsSync(join(migrationsFolder, 'meta', '_journal.json'))) return
  if (db.url.startsWith('file:')) await mkdir(resolve(db.url.slice('file:'.length), '..'), { recursive: true })
  await migrate(useDb(), { migrationsFolder })
})
